// One Slack message per 20 new jobs, so a busy day never floods the channel.
const PER_MESSAGE = 20;
const jobs = $input.all().map((item) => item.json).filter((j) => j && j.id && j.title);
if (jobs.length === 0) return [];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = (u) => String(u ?? '').replace(/\|/g, '%7C').replace(/>/g, '%3E');
const money = (n) => Math.round(n).toLocaleString('en-US');

jobs.sort((a, b) => String(a.company).localeCompare(String(b.company)) || String(a.title).localeCompare(String(b.title)));
const lines = jobs.map((j) => {
  const where = [j.location, j.remote ? 'remote' : ''].filter(Boolean).join(', ');
  let pay = '';
  if (j.salary_min != null || j.salary_max != null) {
    const range = [j.salary_min, j.salary_max].filter((v) => v != null).map(money).join('-');
    pay = ` | ${j.salary_currency || ''} ${range}${j.salary_period ? ' per ' + j.salary_period : ''}`;
  }
  const title = j.url ? `<${link(j.url)}|${esc(j.title)}>` : esc(j.title);
  return `• ${title} at *${esc(j.company || j.board)}*${where ? ' (' + esc(where) + ')' : ''}${esc(pay)}`;
});

const parts = Math.ceil(lines.length / PER_MESSAGE);
const out = [];
for (let p = 0; p < parts; p++) {
  const head = `*${jobs.length} new job${jobs.length === 1 ? '' : 's'} at your target companies*` + (parts > 1 ? ` (${p + 1}/${parts})` : '');
  out.push({ json: { text: [head, ...lines.slice(p * PER_MESSAGE, (p + 1) * PER_MESSAGE)].join('\n') } });
}
return out;
